const today = new Date().toISOString().slice(0, 10);
const rows = $input.all().map(function (i) { return i.json; });
const held = {};
rows.forEach(function (r) { if (r.status === 'hold_confirmed' && r.held_slot) { held[r.held_slot] = true; } });
const out = [];
rows.forEach(function (r) {
  if (r.status !== 'new') { return; }
  const first = String(r.name || 'there').split(' ')[0];
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(r.pref_date || '')) || r.pref_date < today) {
    out.push({ json: { request_key: r.request_key, status: 'needs_info', proposed_slots: '', note: 'Need a valid future date before proposing times.' } });
    return;
  }
  const times = r.pref_period === 'morning' ? ['09:00', '10:30', '11:30'] : ['13:00', '14:30', '16:00'];
  const free = times.map(function (t) { return r.pref_date + ' ' + t; }).filter(function (s) { return !held[s]; });
  if (free.length === 0) {
    out.push({ json: { request_key: r.request_key, status: 'needs_info', proposed_slots: '', note: 'No free times that day. Ask for another date.' } });
    return;
  }
  const body = 'Hi ' + first + ',\n\nThanks for asking about ' + r.property + '. These times are open: ' + free.join(', ') + '. Which works best?\n\n[Your name]\n\n[DRAFT - NOT SENT - requires human approval]';
  out.push({ json: { request_key: r.request_key, status: 'proposed', proposed_slots: free.join(' | '), note: body } });
});
return out;
